"""extends the vscode launch.json generated by 'fips gen'

Adds an editor variant (-editor) of each native debug launch config.
fips imports all project verbs before running any command, so wrapping
the generator here applies to every 'fips gen' without touching fips itself.

vscode_launch
"""

from mod import log
from mod.tools import vscode
import copy
import json

_write_launch_json = vscode.write_launch_json

def write_launch_json(fips_dir, proj_dir, vscode_dir, cfg, proj_settings) :
    """write the default launch.json, then add -editor variants"""
    _write_launch_json(fips_dir, proj_dir, vscode_dir, cfg, proj_settings)
    if cfg['platform'] == 'emscripten' :
        return
    launch_path = vscode_dir + '/launch.json'
    with open(launch_path, 'r') as f :
        launch = json.load(f)
    editor_configs = []
    for launch_config in launch['configurations'] :
        editor_config = copy.deepcopy(launch_config)
        editor_config['name'] = launch_config['name'].replace('Debug Current Target', 'Debug Current Target as Editor', 1)
        editor_config['args'] = launch_config.get('args', []) + ['-editor']
        editor_configs.append(editor_config)
    launch['configurations'] += editor_configs
    log.info('  adding editor launch configs to {}'.format(launch_path))
    with open(launch_path, 'w') as f :
        json.dump(launch, f, indent=1, separators=(',',':'))

vscode.write_launch_json = write_launch_json

def run(fips_dir, proj_dir, args) :
    log.info("vscode_launch has no commands, editor launch configs are added by 'fips gen'")

def help() :
    log.info(log.YELLOW +
             "fips vscode_launch\n" + log.DEF +
             "    (no-op) 'fips gen' adds -editor variants to the vscode launch.json")
